/**
 * @param {number[]} digits
 * @return {number}
 */
var totalNumbers = function(digits) {
    const n = digits.length;
    let res = new Set();

    for (let i = 0; i < n; i++) {
        if (digits[i] === 0) continue;

        for (let j = 0; j < n; j++) {
            if (j === i) continue;

            for (let k = 0; k < n; k++) {
                if (k === i || k === j) continue;
                if (digits[k] & 1) continue;

                res.add(digits[i] + ':' + digits[j] + ':' + digits[k]);
            }
        }
    }

    return res.size;
};

/**
 * @param {number[]} digits
 * @return {number}
 */
var totalNumbers = function(digits) {
    const freq = Array(10).fill(0);

    for (const digit of digits) {
        freq[digit]++;
    }

    let res = 0;

    for (let i = 1; i <= 9; i++) {
        if (freq[i] === 0) continue;
        freq[i]--;

        for (let j = 0; j <= 9; j++) {
            if (freq[j] === 0) continue;
            freq[j]--;

            for (let k = 0; k <= 8; k += 2) {
                if (freq[k] === 0) continue;

                res++;
            }

            freq[j]++;
        }

        freq[i]++;
    }

    return res;
};
